c = C()
print(c.x)

以下代码中，c.x = 10 会执行什么？
class D:
    def __get__(self, obj, objtype=None):
        return obj._x
    def __set__(self, obj, value):
        obj._x = value
class C:
    x = D()
c = C()
c.x = 10
